from pathlib import Path
import json, shutil, os, re, html as _html
p=Path(__file__).parent; d=p/'dist'
# Deployment settings. The defaults are the live growthelement.ai settings, so a plain
# `python3 consolidate.py` reproduces the published site. Environment variables override
# them (never put credentials here):
#   GE_MODE         launch (default) or review. Launch removes noindex from the public pages,
#                   removes the footer review link, adds canonical/Open Graph metadata, and
#                   writes robots.txt and sitemap.xml. review.html always stays noindex.
#   GE_SITE_URL     Final https:// domain (default https://growthelement.ai).
#   GE_BOOKING_URL  https:// booking calendar, used as the fallback link on book.html, or as
#                   the direct button target when GE_FILLOUT_ID is empty.
#   GE_FILLOUT_ID   Fillout form id embedded on book.html. When set, every booking button
#                   goes to book.html. Set GE_FILLOUT_ID= and GE_BOOKING_URL= with
#                   GE_MODE=review to get the original v7 review build with its brief-only modal.
MODE=os.environ.get('GE_MODE','launch').strip().lower()
BOOKING_URL=os.environ.get('GE_BOOKING_URL','https://growthelement.fillout.com/meet-with-growth-element').strip()
FILLOUT_ID=os.environ.get('GE_FILLOUT_ID','ggjTZaHU9Uus').strip()
SITE_URL=os.environ.get('GE_SITE_URL','https://growthelement.ai').strip().rstrip('/')
if FILLOUT_ID and not re.fullmatch(r'[A-Za-z0-9]+',FILLOUT_ID):raise SystemExit('GE_FILLOUT_ID must be alphanumeric')
if MODE not in ('review','launch'):raise SystemExit('GE_MODE must be review or launch')
if BOOKING_URL and not BOOKING_URL.startswith('https://'):raise SystemExit('GE_BOOKING_URL must start with https://')
if MODE=='launch' and not SITE_URL.startswith('https://'):raise SystemExit('Launch mode needs GE_SITE_URL=https://<final domain>')
if MODE=='launch' and not (BOOKING_URL or FILLOUT_ID):raise SystemExit('Launch mode needs GE_FILLOUT_ID or GE_BOOKING_URL: the brief-only modal must not ship publicly')
# Preserve the comparison entry without rebuilding or altering the original concepts.
if not (d/'concepts.html').exists():shutil.copyfile(d/'index.html',d/'concepts.html')
